function parseDate(v) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'number') { const d = new Date(Math.round((v - 25569) * 86400000)); d.setHours(0, 0, 0, 0); return d; }
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  m = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})$/); // DD/MM/YYYY
  if (m) return new Date(+m[3], +m[2] - 1, +m[1]);
  const d = new Date(s); return isNaN(d) ? null : d;
}
const fmt = d => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
const DOCS = [
  { key: 'rc',        label: 'Registration Certificate (RC)', col: 'rc_expiry' },
  { key: 'insurance', label: 'Insurance',                     col: 'insurance_expiry' },
  { key: 'puc',       label: 'PUC Certificate',               col: 'puc_expiry' },
  { key: 'fitness',   label: 'Fitness Certificate',           col: 'fitness_expiry' },
  { key: 'permit',    label: 'Permit',                        col: 'permit_expiry' }
];
const STAGES = [0, 3, 7, 15, 30];
const today = new Date(); today.setHours(0, 0, 0, 0);
const weekNo = Math.floor(today.getTime() / (7 * 86400000));

const alerted = new Set(), tasked = new Set();
for (const l of $('Read Alert Log').all()) {
  String(l.json.alert_keys || '').split(';').map(k => k.trim()).filter(Boolean).forEach(k => alerted.add(k));
  String(l.json.task_keys || '').split(';').map(k => k.trim()).filter(Boolean).forEach(k => tasked.add(k));
}

const out = [];
for (const item of $('Read Fleet Register').all()) {
  const r = item.json;
  if (!r.vehicle_no || String(r.active || 'yes').toLowerCase() === 'no') continue;
  const vehicle = String(r.vehicle_no).toUpperCase().replace(/\s+/g, '');
  const docAlerts = [], allDue = [], expired = [], newAlertKeys = [], newTaskKeys = [], newTaskDocs = [];

  for (const d of DOCS) {
    const exp = parseDate(r[d.col]);
    if (!exp) continue;
    const daysLeft = Math.round((exp - today) / 86400000);
    if (daysLeft < 0) expired.push(d.label);
    if (daysLeft > STAGES[STAGES.length - 1]) continue;
    const expStr = fmt(exp);
    allDue.push({ doc: d.label, expiry: expStr, days_left: daysLeft });
    const stage = daysLeft < 0 ? `expired-w${weekNo}` : String(STAGES.find(s => daysLeft <= s));
    const alertKey = `${vehicle}|${d.key}|${expStr}|${stage}`;
    const taskKey = `${vehicle}|${d.key}|${expStr}`;
    if (!alerted.has(alertKey)) {
      docAlerts.push({ doc: d.label, expiry: expStr, days_left: daysLeft, status: daysLeft < 0 ? 'EXPIRED' : `${daysLeft} days left` });
      newAlertKeys.push(alertKey);
    }
    if (!tasked.has(taskKey)) { newTaskKeys.push(taskKey); newTaskDocs.push(d.label); }
  }

  out.push({ json: {
    vehicle_no: vehicle,
    vehicle_no_raw: String(r.vehicle_no),
    vehicle_type: r.vehicle_type || '',
    chassis_last5: r.chassis_last5 ? String(r.chassis_last5) : '',
    driver_name: r.driver_name || 'Driver',
    driver_telegram_chat_id: r.driver_telegram_chat_id ? String(r.driver_telegram_chat_id) : '',
    manager_email: r.manager_email || '',
    current_dispatch_status: String(r.dispatch_status || 'ACTIVE').toUpperCase(),
    doc_alerts: docAlerts,
    all_due_docs: allDue,
    expired_docs: expired,
    new_alert_keys: newAlertKeys,
    new_task_keys: newTaskDocs.length && docAlerts.length ? newTaskKeys : [],
    new_task_docs: docAlerts.length ? newTaskDocs : [],
    known_challan_nos: [...alerted].filter(k => k.startsWith(`${vehicle}|challan|`)).map(k => k.split('|')[2])
  }});
}
return out;

const v = $('Evaluate Document Expiry & Dedupe').item.json;
const res = $json || {};
const apiError = !!res.error;
const raw = res.challans || res.data?.challans || res.data?.challan_details || res.result?.challans || res.result || res.data || [];
const list = Array.isArray(raw) ? raw : [];

const pending = list
  .filter(c => !/paid|disposed|closed|settled/i.test(String(c.status || c.challan_status || '')))
  .map(c => ({
    challan_no: String(c.challan_no || c.challan_number || c.challanNo || c.id || ''),
    date: c.date || c.challan_date || c.challanDate || '',
    amount: Number(c.amount || c.fine_amount || c.penalty || 0),
    offence: c.offence || c.offense || c.offence_details || c.violation || '',
    state: c.state || c.state_code || ''
  }));
const known = new Set(v.known_challan_nos || []);
const newChallans = pending.filter(c => c.challan_no && !known.has(c.challan_no));
const pendingTotal = pending.reduce((s, c) => s + c.amount, 0);

// ── Compliance risk score (0–100) ──
let score = 0;
score += v.expired_docs.length * 40;
for (const d of v.all_due_docs) if (d.days_left >= 0) score += d.days_left <= 7 ? 15 : d.days_left <= 15 ? 8 : 4;
score += Math.min(20, pending.length * 4) + Math.min(15, Math.floor(pendingTotal / 1000));
score = Math.min(100, score);
const riskLevel = score >= 60 ? 'HIGH' : score >= 30 ? 'MEDIUM' : 'LOW';

// ── Dispatch gate: any expired statutory document = off-road ──
const dispatchStatus = v.expired_docs.length ? 'BLOCKED' : 'ACTIVE';
const prev = ['BLOCKED', 'ACTIVE'].includes(v.current_dispatch_status) ? v.current_dispatch_status : 'ACTIVE';

return { json: {
  ...v,
  challan_check_status: apiError ? 'api_error' : 'ok',
  pending_challans: pending,
  pending_challan_total: pendingTotal,
  new_challans: newChallans,
  new_alert_keys: [...v.new_alert_keys, ...newChallans.map(c => `${v.vehicle_no}|challan|${c.challan_no}`)],
  risk_score: score,
  risk_level: riskLevel,
  dispatch_status: dispatchStatus,
  blocked_reason: v.expired_docs.length ? `Expired: ${v.expired_docs.join(', ')}` : '',
  dispatch_changed: dispatchStatus !== prev,
  needs_action: v.doc_alerts.length > 0 || newChallans.length > 0
}};

