const DEFAULT_MANAGER_EMAIL = 'user@example.com';
const all = $('Score Risk & Dispatch Gate').all().map(i => i.json);
const acted = all.filter(r => r.needs_action);
const ai = $('AI Compose Driver Alerts').all().map(i => {
  let c = i.json.message?.content ?? {};
  if (typeof c === 'string') { try { c = JSON.parse(c); } catch (e) { c = {}; } }
  return c;
});
const apiErrors = all.filter(r => r.challan_check_status === 'api_error').map(r => r.vehicle_no);
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;');
const riskColor = l => l === 'HIGH' ? '#c0392b' : l === 'MEDIUM' ? '#d35400' : '#27ae60';

const groups = {};
acted.forEach((r, i) => {
  const to = r.manager_email || DEFAULT_MANAGER_EMAIL;
  (groups[to] ||= []).push({ ...r, ai: ai[i] || {} });
});

return Object.entries(groups).map(([to, rows]) => {
  rows.sort((a, b) => b.risk_score - a.risk_score);
  const blocked = all.filter(r => (r.manager_email || DEFAULT_MANAGER_EMAIL) === to && r.dispatch_status === 'BLOCKED');
  const challanAmt = rows.reduce((n, r) => n + r.new_challans.reduce((s, c) => s + c.amount, 0), 0);
  const tr = rows.map(r => `<tr>
    <td><b>${esc(r.vehicle_no)}</b>${r.dispatch_status === 'BLOCKED' ? ' <span style="background:#c0392b;color:#fff;padding:1px 5px;border-radius:3px;font-size:11px">OFF-ROAD</span>' : ''}<br><small>${esc(r.driver_name)}</small></td>
    <td style="color:${riskColor(r.risk_level)};font-weight:bold">${r.risk_level}<br><small>${r.risk_score}/100</small></td>
    <td>${r.doc_alerts.map(d => `<span style="color:${d.days_left < 0 ? '#c0392b' : d.days_left <= 7 ? '#d35400' : '#333'}">${esc(d.doc)} – ${esc(d.status)} (${d.expiry})</span>`).join('<br>') || '—'}</td>
    <td>${r.new_challans.length ? r.new_challans.map(c => `${esc(c.challan_no)} ₹${c.amount} ${esc(c.offence)}`).join('<br>') : '—'}</td>
    <td>${esc(r.ai.manager_summary || '')}</td></tr>`).join('');
  const html = `<div style="font-family:Arial,sans-serif">
  <h2>Fleet compliance digest – ${new Date().toISOString().slice(0, 10)}</h2>
  <p><b>${rows.length}</b> vehicle(s) need attention · <b style="color:#c0392b">${blocked.length}</b> off-road · <b>₹${challanAmt}</b> in new challans</p>
  <table border="1" cellpadding="6" style="border-collapse:collapse;font-size:13px">
  <tr style="background:#f0f0f0"><th>Vehicle</th><th>Risk</th><th>Documents</th><th>New e-challans</th><th>Summary</th></tr>${tr}</table>
  ${apiErrors.length ? `<p style="color:#c0392b">⚠️ e-challan check failed for: ${apiErrors.join(', ')}</p>` : ''}
  <p style="color:#888;font-size:12px">Drivers alerted on Telegram and can reply with a photo of the renewed document; renewal tasks created in ClickUp.</p></div>`;
  return { json: { to, subject: `🚚 Fleet compliance: ${rows.length} vehicle(s) need action${blocked.length ? ` · ${blocked.length} OFF-ROAD` : ''}`, html } };
});

