// Continue only if: message has an image AND sender is a registered driver
const msg = $('On Driver Telegram Message').first().json.message || {};
const photos = msg.photo || [];
const doc = msg.document && /^image\//.test(msg.document.mime_type || '') ? msg.document : null;
const fileId = photos.length ? photos[photos.length - 1].file_id : doc?.file_id;
const rows = $input.all().map(i => i.json).filter(r => r.vehicle_no);
if (!fileId || !rows.length) return [];

// Drivers with several vehicles: pick the one named in the caption
const norm = s => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const caption = norm(msg.caption);
const row = rows.find(r => caption.includes(norm(r.vehicle_no))) || rows[0];
return [{ json: { file_id: fileId, chat_id: msg.chat.id, caption: msg.caption || '', register: row } }];

function parseDate(v) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'number') { const d = new Date(Math.round((v - 25569) * 86400000)); d.setHours(0, 0, 0, 0); return d; }
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  m = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})$/); // DD/MM/YYYY
  if (m) return new Date(+m[3], +m[2] - 1, +m[1]);
  const d = new Date(s); return isNaN(d) ? null : d;
}
const fmt = d => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
const DOCS = [
  { key: 'rc',        label: 'Registration Certificate (RC)', col: 'rc_expiry' },
  { key: 'insurance', label: 'Insurance',                     col: 'insurance_expiry' },
  { key: 'puc',       label: 'PUC Certificate',               col: 'puc_expiry' },
  { key: 'fitness',   label: 'Fitness Certificate',           col: 'fitness_expiry' },
  { key: 'permit',    label: 'Permit',                        col: 'permit_expiry' }
];
const g = $('Accept Only Driver Photos').first().json;
const reg = g.register;
const today = new Date(); today.setHours(0, 0, 0, 0);
const norm = s => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '');

const raw = $json.content ?? $json.message?.content ?? $json.text ?? '';
let d = {};
try { d = typeof raw === 'object' ? raw : JSON.parse(String(raw).replace(/```json|```/g, '').trim()); } catch (e) { d = {}; }

const docDef = DOCS.find(x => x.key === d.doc_type);
const exp = parseDate(d.valid_until);
const current = docDef ? parseDate(reg[docDef.col]) : null;
const issues = [];
if (!docDef) issues.push('could not identify the document type');
if (d.vehicle_no && norm(d.vehicle_no) !== norm(reg.vehicle_no)) issues.push(`vehicle number on document (${d.vehicle_no}) does not match ${reg.vehicle_no}`);
if (!exp) issues.push('validity date not readable');
else if (exp <= today) issues.push(`document shows validity until ${fmt(exp)}, which is already over`);
else if (current && exp <= current) issues.push(`validity ${fmt(exp)} is not newer than our record (${fmt(current)})`);
if (Number(d.confidence || 0) < 0.6) issues.push('photo not clear enough');

const valid = issues.length === 0;
const stillExpired = DOCS.filter(x => !docDef || x.key !== docDef.key)
  .filter(x => { const e = parseDate(reg[x.col]); return e && e < today; }).map(x => x.label);

const ctx = {
  valid, issues, chat_id: g.chat_id, vehicle_no: reg.vehicle_no, driver_name: reg.driver_name || 'Driver',
  doc_label: docDef?.label || 'Unknown', new_expiry: exp ? fmt(exp) : '', old_expiry: current ? fmt(current) : 'n/a',
  document_no: d.document_no || '', issuer: d.issuer || '', confidence: d.confidence ?? 0, still_expired: stillExpired
};
if (!valid) return [{ json: { ctx } }];

// Only sheet columns at top level → auto-mapped into the register update
return [{ json: {
  vehicle_no: reg.vehicle_no,
  [docDef.col]: fmt(exp),
  dispatch_status: stillExpired.length ? 'BLOCKED' : 'ACTIVE',
  blocked_reason: stillExpired.length ? `Expired: ${stillExpired.join(', ')}` : '',
  dispatch_updated_at: new Date().toISOString(),
  last_doc_update: `${docDef.label} via Telegram ${new Date().toISOString().slice(0, 10)}`,
  ctx
}}];

